"use client";

import { useAccount } from "@/components/account-context";
import { useDashboardUser } from "@/components/layout/dashboard-user";
import { MissionDescriptionEditor } from "@/components/mission-description-editor";
import { DiscordAvatar } from "@/components/actor-trace";
import {
  createSceneWorkshop, deleteSceneWorkshop, duplicateSceneWorkshop, getSceneWorkshop,
  listSceneWorkshops, saveSceneWorkshop, listDeletedSceneWorkshops, restoreDeletedSceneWorkshop, permanentlyDeleteSceneWorkshop, restoreSceneWorkshopVersion, compareWorkshopVersion, type SceneWorkshop, type WorkshopBoardItem,
} from "@/lib/scene-workshop";
import { listAllAccounts, type RefgmAccount } from "@/lib/accounts";
import { getSupabaseBrowserClient } from "@/lib/supabase";
import { cn } from "@/lib/utils";
import { AnimatePresence, motion } from "framer-motion";
import {
  ArchiveRestore, ArrowLeft, Brush, Check, ChevronRight, Copy, Eraser, ExternalLink,
  FilePenLine, ImagePlus, LayoutGrid, Map, MousePointer2, Network, Plus, Redo2, RectangleHorizontal,
  History, Save, Search, Share2, StickyNote, Trash2, Undo2, X,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

const COLORS = ["#38bdf8", "#a78bfa", "#34d399", "#fbbf24", "#fb7185", "#f472b6", "#ffffff"];
type Tool = "select" | "pen" | "rect" | "arrow";

export function SceneWorkshopPanel() {
  const { account } = useAccount();
  const user = useDashboardUser();
  const actor = useMemo(() => ({ id: account.userId, name: account.displayName || user.name || "GameMaster", avatarUrl: account.discordAvatarUrl || user.image || null }), [account, user]);
  const [rows, setRows] = useState<SceneWorkshop[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [trashOpen,setTrashOpen]=useState(false);

  const refresh = useCallback(() => setRows(listSceneWorkshops(actor.id)), [actor.id]);
  useEffect(() => {
    refresh();
    window.addEventListener("refgm:scene-workshops-updated", refresh);
    window.addEventListener("storage", refresh);
    return () => { window.removeEventListener("refgm:scene-workshops-updated", refresh); window.removeEventListener("storage", refresh); };
  }, [refresh]);

  function create() { const row = createSceneWorkshop({ ownerId: actor.id, ownerName: actor.name, ownerAvatarUrl: actor.avatarUrl }); refresh(); setActiveId(row.id); }
  if (activeId) return <WorkshopEditor key={activeId} id={activeId} actor={actor} onBack={() => { setActiveId(null); refresh(); }} />;

  return <main className="lab-bg min-h-dvh p-5 text-white sm:p-8">
    <div className="mx-auto max-w-7xl">
      <header className="relative overflow-hidden rounded-[2rem] border border-violet-300/15 bg-gradient-to-br from-violet-300/[0.08] via-white/[0.025] to-transparent p-6 shadow-[0_28px_90px_rgba(0,0,0,.25)] sm:p-8"><div className="pointer-events-none absolute -right-20 -top-32 h-80 w-80 rounded-full bg-violet-400/10 blur-[90px]"/><div className="relative flex flex-col gap-6 sm:flex-row sm:items-end sm:justify-between">
        <div><p className="text-xs font-medium uppercase tracking-[.24em] text-violet-300/60">Création collaborative</p><h1 className="mt-3 text-4xl font-medium tracking-tight">Atelier de scène</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-white/40">Écris, dessine, organise tes idées sur la WebMap et construis une scène avec plusieurs GameMasters dans un espace partagé.</p><div className="mt-5 flex flex-wrap gap-2">{['Éditeur riche','Tableau visuel','WebMap annotable','Travail partagé'].map((label)=><span key={label} className="rounded-full border border-white/[0.08] bg-black/15 px-3 py-1.5 text-[10px] uppercase tracking-wider text-white/35">{label}</span>)}</div></div>
        <div className="flex gap-2"><button onClick={()=>setTrashOpen((value)=>!value)} className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.035] px-4 py-3 text-sm text-white/55 hover:bg-white/[0.07]"><Trash2 className="h-4 w-4"/>Corbeille</button><button onClick={create} className="flex items-center justify-center gap-2 rounded-xl bg-violet-400 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-violet-300"><Plus className="h-4 w-4" />Nouvel atelier</button></div>
      </div></header>
      {trashOpen?<TrashPanel actorId={actor.id} onChange={refresh}/>:null}
      {rows.length ? <div className="mt-8 grid gap-5 md:grid-cols-2 xl:grid-cols-3">{rows.map((row, index) => <motion.article whileHover={{ y: -5 }} key={row.id} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index * .04 }} className="group relative overflow-hidden rounded-3xl border border-white/[0.08] bg-gradient-to-br from-white/[0.045] to-white/[0.015] p-5 shadow-[0_18px_55px_rgba(0,0,0,.2)] transition hover:border-violet-400/25"><div className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-violet-300/40 to-transparent"/>
        <button className="block w-full text-left" onClick={() => setActiveId(row.id)}><div className="flex items-start justify-between"><span className="rounded-xl border border-violet-400/15 bg-violet-400/[0.07] p-2.5 text-violet-300"><FilePenLine className="h-5 w-5" /></span><span className="rounded-full border border-white/10 px-2.5 py-1 text-[10px] uppercase tracking-wider text-white/35">{row.status === "READY" ? "Prêt" : "Brouillon"}</span></div><h2 className="mt-5 truncate text-lg font-medium">{row.title}</h2><p className="mt-2 line-clamp-2 min-h-10 text-sm leading-5 text-white/35">{row.summary || row.documentText || "Atelier vide. Commence à imaginer la scène."}</p><div className="mt-5 flex items-center justify-between border-t border-white/[0.06] pt-4"><div className="flex -space-x-2"><DiscordAvatar name={row.ownerName} url={row.ownerAvatarUrl} size={28} />{row.collaborators.slice(0, 3).map((member) => <DiscordAvatar key={member.userId} name={member.displayName} url={member.avatarUrl} size={28} />)}</div><ChevronRight className="h-4 w-4 text-white/20 transition group-hover:translate-x-1 group-hover:text-violet-300" /></div></button>
        <div className="mt-3 flex gap-2"><button title="Dupliquer" onClick={() => { duplicateSceneWorkshop(row, actor); refresh(); }} className="rounded-lg p-2 text-white/25 hover:bg-white/[0.05] hover:text-white"><Copy className="h-4 w-4" /></button>{row.ownerId === actor.id ? <button title="Supprimer" onClick={() => { if (confirm("Supprimer cet atelier ?")) { deleteSceneWorkshop(row.id); refresh(); } }} className="rounded-lg p-2 text-white/25 hover:bg-rose-400/10 hover:text-rose-300"><Trash2 className="h-4 w-4" /></button> : null}</div>
      </motion.article>)}</div> : <div className="mt-20 flex flex-col items-center text-center"><div className="rounded-3xl border border-white/[0.07] bg-white/[0.025] p-6 text-white/20"><LayoutGrid className="h-10 w-10" /></div><h2 className="mt-5 text-lg font-medium">Ton atelier est vide</h2><p className="mt-2 text-sm text-white/35">Crée ton premier projet et invite d’autres GM.</p></div>}
    </div>
  </main>;
}

function WorkshopEditor({ id, actor, onBack }: { id: string; actor: { id: string; name: string; avatarUrl: string | null }; onBack: () => void }) {
  const [draft, setDraft] = useState<SceneWorkshop | null>(() => getSceneWorkshop(id));
  const [tab, setTab] = useState<"document" | "board" | "map" | "network">("document");
  const [sharing, setSharing] = useState(false);
  const [historyOpen,setHistoryOpen]=useState(false);
  const [saved, setSaved] = useState(true);
  const applyRemoteChange = useCallback((patch: Partial<SceneWorkshop>) => setDraft((current) => current ? { ...current, ...patch } : current), []);
  const { peers, broadcastChange } = useWorkshopPresence(id, actor, applyRemoteChange);
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const broadcastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const queuedPatch = useRef<Partial<SceneWorkshop>>({});

  const canEdit = Boolean(draft && (draft.ownerId === actor.id || draft.collaborators.some((m) => m.userId === actor.id && m.permission === "EDIT")));
  const update = useCallback((patch: Partial<SceneWorkshop>) => {
    setDraft((current) => current ? { ...current, ...patch, updatedById: actor.id, updatedByName: actor.name } : current);
    setSaved(false);
    queuedPatch.current = { ...queuedPatch.current, ...patch, updatedById: actor.id, updatedByName: actor.name };
    if (broadcastTimer.current) clearTimeout(broadcastTimer.current);
    broadcastTimer.current = setTimeout(() => { broadcastChange(queuedPatch.current); queuedPatch.current = {}; }, 140);
  }, [actor, broadcastChange]);
  useEffect(() => {
    if (!draft || saved) return;
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => { saveSceneWorkshop(draft); setSaved(true); }, 850);
    return () => { if (saveTimer.current) clearTimeout(saveTimer.current); };
  }, [draft, saved]);
  useEffect(() => {
    const receiveRemoteUpdate = () => {
      if (!saved) return;
      const remote = getSceneWorkshop(id);
      if (remote && remote.updatedAt !== draft?.updatedAt) setDraft(remote);
    };
    window.addEventListener("refgm:scene-workshops-updated", receiveRemoteUpdate);
    return () => window.removeEventListener("refgm:scene-workshops-updated", receiveRemoteUpdate);
  }, [draft?.updatedAt, id, saved]);

  if (!draft) return <div className="p-10 text-white">Atelier introuvable.</div>;
  return <main className="flex min-h-dvh flex-col bg-[#08090b] text-white">
    <header className="sticky top-0 z-40 flex min-h-16 flex-wrap items-center gap-3 border-b border-white/[0.07] bg-[#0a0b0e]/90 px-4 py-3 backdrop-blur-2xl">
      <button onClick={onBack} className="rounded-xl p-2.5 text-white/45 hover:bg-white/[0.06] hover:text-white"><ArrowLeft className="h-4 w-4" /></button>
      <div className="min-w-0 flex-1"><input disabled={!canEdit} value={draft.title} onChange={(e) => update({ title: e.target.value })} className="w-full max-w-xl bg-transparent text-base font-medium outline-none placeholder:text-white/25" /><p className="mt-0.5 flex items-center gap-1.5 text-[10px] uppercase tracking-wider text-white/25">{saved ? <><Check className="h-3 w-3 text-emerald-400" />Sauvegardé</> : <><Save className="h-3 w-3 animate-pulse" />Sauvegarde…</>}</p></div>
      <div className="hidden items-center gap-2 sm:flex"><span className="flex h-2 w-2 rounded-full bg-emerald-400 shadow-[0_0_12px_#34d399]" /><span className="text-[10px] uppercase tracking-wider text-white/30">{peers.length || 1} en ligne</span><div className="flex -space-x-2"><DiscordAvatar name={actor.name} url={actor.avatarUrl} size={32} />{peers.filter((p) => p.userId !== actor.id).slice(0, 4).map((p) => <DiscordAvatar key={p.userId} name={p.name} url={p.avatarUrl} size={32} />)}</div></div>
      <button onClick={() => setSharing(true)} className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.04] px-3.5 py-2.5 text-xs text-white/70 hover:bg-white/[0.08]"><Share2 className="h-4 w-4" />Partager</button>
      <button onClick={()=>setHistoryOpen(true)} className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.04] px-3.5 py-2.5 text-xs text-white/70 hover:bg-white/[0.08]"><History className="h-4 w-4"/>Historique</button>
      {draft.ownerId === actor.id ? <button onClick={() => update({ status: draft.status === "READY" ? "DRAFT" : "READY" })} className={cn("rounded-xl px-4 py-2.5 text-xs font-semibold", draft.status === "READY" ? "border border-emerald-400/20 bg-emerald-400/10 text-emerald-200" : "bg-violet-400 text-slate-950")}>{draft.status === "READY" ? "Prêt à envoyer" : "Marquer comme prêt"}</button> : null}
    </header>
    <div className="flex items-center justify-center overflow-x-auto border-b border-white/[0.06] bg-black/20 p-2"><div className="flex rounded-xl border border-white/[0.07] bg-white/[0.025] p-1">{([['document','Scénario',FilePenLine],['board','Plan & dessin',Brush],['network','Blocs reliés',Network],['map','WebMap',Map]] as const).map(([value,label,Icon]) => <button key={value} onClick={() => setTab(value)} className={cn("flex shrink-0 items-center gap-2 rounded-lg px-4 py-2 text-xs transition", tab === value ? "bg-white/10 text-white" : "text-white/35 hover:text-white/70")}><Icon className="h-4 w-4" />{label}</button>)}</div></div>
    <section className="flex-1 p-4 sm:p-7">{tab === "document" ? <div className="mx-auto max-w-5xl"><input disabled={!canEdit} value={draft.summary} onChange={(e) => update({ summary: e.target.value })} placeholder="Résumé rapide de la scène…" className="mb-4 w-full rounded-xl border border-white/[0.07] bg-white/[0.025] px-4 py-3 text-sm outline-none placeholder:text-white/20 focus:border-violet-400/25" /><MissionDescriptionEditor value={draft.documentHtml} onChange={(html, plain) => update({ documentHtml: html, documentText: plain })} placeholder="Construisez votre scène ensemble… Contexte, objectifs, déroulement, personnages, rebondissements et fins possibles." className="rounded-2xl border-white/[0.08] bg-[#0d0f13] shadow-2xl" /></div> : tab === "board" ? <WorkshopBoard items={draft.boardItems} disabled={!canEdit} onChange={(boardItems) => update({ boardItems })} /> : tab === "network" ? <InfoNetwork blocks={draft.infoBlocks} connections={draft.connections} disabled={!canEdit} onBlocks={(infoBlocks) => update({ infoBlocks })} onConnections={(connections) => update({ connections })} /> : <WebMapPanel items={draft.mapItems} disabled={!canEdit} onChange={(mapItems) => update({ mapItems })} />}</section>
    <LiveCursors peers={peers.filter((peer) => peer.userId !== actor.id)} />
    <AnimatePresence>{sharing ? <ShareDialog draft={draft} actor={actor} onClose={() => setSharing(false)} onChange={(collaborators) => update({ collaborators })} /> : null}</AnimatePresence>
    <AnimatePresence>{historyOpen?<VersionDialog draft={draft} actor={actor} onClose={()=>setHistoryOpen(false)} onRestore={(versionId)=>{const restored=restoreSceneWorkshopVersion(draft.id,versionId,actor);if(restored){setDraft(restored);setSaved(true);}setHistoryOpen(false);}}/>:null}</AnimatePresence>
  </main>;
}

function TrashPanel({actorId,onChange}:{actorId:string;onChange:()=>void}){const rows=listDeletedSceneWorkshops(actorId);return <section className="mt-6 rounded-2xl border border-white/[0.07] bg-white/[0.025] p-4"><div className="mb-3"><h2 className="text-sm font-medium">Corbeille temporaire</h2><p className="mt-1 text-xs text-white/30">Les ateliers supprimés restent récupérables tant que tu ne les effaces pas définitivement.</p></div>{rows.length?<div className="space-y-2">{rows.map((row)=><div key={row.id} className="flex items-center gap-3 rounded-xl border border-white/[0.06] p-3"><div className="min-w-0 flex-1"><p className="truncate text-sm text-white/75">{row.title}</p><p className="text-[10px] text-white/25">Supprimé le {new Date(row.deletedAt||"").toLocaleString("fr-FR")}</p></div><button onClick={()=>{restoreDeletedSceneWorkshop(row.id);onChange();}} className="flex items-center gap-1.5 rounded-lg bg-emerald-400/10 px-3 py-2 text-xs text-emerald-200"><ArchiveRestore className="h-3.5 w-3.5"/>Restaurer</button><button onClick={()=>{if(confirm("Supprimer définitivement cet atelier ?")){permanentlyDeleteSceneWorkshop(row.id);onChange();}}} className="rounded-lg p-2 text-white/30 hover:bg-rose-400/10 hover:text-rose-300"><Trash2 className="h-4 w-4"/></button></div>)}</div>:<p className="py-6 text-center text-sm text-white/25">La corbeille est vide.</p>}</section>}

function VersionDialog({draft,actor,onClose,onRestore}:{draft:SceneWorkshop;actor:{id:string;name:string};onClose:()=>void;onRestore:(id:string)=>void}){const [selected,setSelected]=useState(draft.versions.at(-1)?.id||"");const version=draft.versions.find((item)=>item.id===selected);const comparison=version?compareWorkshopVersion(draft,version):null;return <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-md"><motion.div initial={{scale:.97,y:10}} animate={{scale:1,y:0}} className="w-full max-w-3xl rounded-2xl border border-white/10 bg-[#101216] p-6"><div className="flex items-start justify-between"><div><p className="text-xs uppercase tracking-wider text-violet-300/55">Sauvegardes automatiques</p><h2 className="mt-2 text-xl font-medium">Historique de l’atelier</h2><p className="mt-1 text-xs text-white/35">Une version est conservée toutes les deux minutes lorsqu’un changement est détecté.</p></div><button onClick={onClose} className="rounded-lg p-2 text-white/35 hover:bg-white/[0.06]"><X className="h-4 w-4"/></button></div>{draft.versions.length?<div className="mt-6 grid gap-4 md:grid-cols-[280px_1fr]"><div className="max-h-96 space-y-2 overflow-y-auto">{[...draft.versions].reverse().map((item)=><button key={item.id} onClick={()=>setSelected(item.id)} className={cn("w-full rounded-xl border p-3 text-left",selected===item.id?"border-violet-400/25 bg-violet-400/[0.07]":"border-white/[0.07] bg-white/[0.02]")}><p className="text-sm text-white/75">{item.label}</p><p className="mt-1 text-[10px] text-white/30">{new Date(item.createdAt).toLocaleString("fr-FR")} · {item.createdByName}</p></button>)}</div>{version&&comparison?<div className="rounded-xl border border-white/[0.07] bg-black/20 p-4"><h3 className="text-sm font-medium">Différences avec maintenant</h3><div className="mt-4 space-y-2 text-xs text-white/50"><p>Titre : {comparison.titleChanged?"modifié":"identique"}</p><p>Résumé : {comparison.summaryChanged?"modifié":"identique"}</p><p>Texte : {comparison.textDelta>=0?"+":""}{comparison.textDelta} caractères</p><p>Plan : {comparison.boardDelta>=0?"+":""}{comparison.boardDelta} éléments</p><p>Carte : {comparison.mapDelta>=0?"+":""}{comparison.mapDelta} annotations</p><p>Blocs : {comparison.blocksDelta>=0?"+":""}{comparison.blocksDelta}</p></div><button onClick={()=>{if(confirm("Restaurer cette version ? La version actuelle sera conservée dans l’historique."))onRestore(version.id);}} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-violet-400 px-4 py-3 text-sm font-semibold text-slate-950"><ArchiveRestore className="h-4 w-4"/>Restaurer cette version</button></div>:null}</div>:<div className="mt-8 rounded-xl border border-dashed border-white/10 py-12 text-center text-sm text-white/30">La première version apparaîtra après une modification sauvegardée.</div>}</motion.div></motion.div>}

function ShareDialog({ draft, actor, onClose, onChange }: { draft: SceneWorkshop; actor: { id: string; name: string; avatarUrl: string | null }; onClose: () => void; onChange: (members: SceneWorkshop["collaborators"]) => void }) {
  const [accounts, setAccounts] = useState<RefgmAccount[]>([]); const [search, setSearch] = useState(""); const [loading, setLoading] = useState(true);
  const owner = draft.ownerId === actor.id;
  useEffect(() => { void listAllAccounts().then((rows) => setAccounts(rows.filter((row) => row.status === "APPROVED" && row.userId !== draft.ownerId))).finally(() => setLoading(false)); }, [draft.ownerId]);
  const visibleAccounts = accounts.filter((row) => `${row.displayName} ${row.userId}`.toLowerCase().includes(search.toLowerCase()) && !draft.collaborators.some((member) => member.userId === row.userId));
  return <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-md" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}><motion.div initial={{ scale: .96, y: 10 }} animate={{ scale: 1, y: 0 }} className="w-full max-w-lg rounded-2xl border border-white/10 bg-[#101216] p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-xs uppercase tracking-[.18em] text-violet-300/60">Collaboration</p><h2 className="mt-2 text-xl font-medium">Partager le brouillon</h2></div><button onClick={onClose} className="rounded-lg p-2 text-white/35 hover:bg-white/[0.06] hover:text-white"><X className="h-4 w-4" /></button></div>
    <div className="mt-6 space-y-3"><Member name={draft.ownerName} avatar={draft.ownerAvatarUrl} label="Propriétaire" />{draft.collaborators.map((member) => <div key={member.userId} className="flex items-center gap-3"><DiscordAvatar name={member.displayName} url={member.avatarUrl} size={38} /><div className="min-w-0 flex-1"><p className="truncate text-sm">{member.displayName}</p><p className="text-xs text-white/25">{member.permission === "EDIT" ? "Peut modifier" : member.permission === "COMMENT" ? "Peut commenter" : "Lecture seule"}</p></div>{owner ? <button onClick={() => onChange(draft.collaborators.filter((m) => m.userId !== member.userId))} className="p-2 text-white/25 hover:text-rose-300"><Trash2 className="h-4 w-4" /></button> : null}</div>)}</div>
    {owner ? <div className="mt-6 rounded-xl border border-white/[0.07] bg-black/20 p-4"><div className="rounded-xl border border-violet-400/15 bg-violet-400/[0.06] p-3 text-xs leading-5 text-violet-100/60"><strong className="text-violet-100/85">Que se passe-t-il après le partage ?</strong><br/>Le GameMaster sélectionné verra automatiquement ce brouillon dans son propre Atelier. Vous pourrez écrire, dessiner, déplacer les blocs et voir vos curseurs simultanément. Chaque changement sera synchronisé et sauvegardé pour tous.</div><p className="mt-4 text-xs font-medium text-white/55">Sélectionner un compte existant</p><div className="relative mt-2"><Search className="absolute left-3 top-3 h-4 w-4 text-white/20"/><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Rechercher un GameMaster…" className="w-full rounded-lg border border-white/10 bg-black/30 py-2.5 pl-12 pr-3 text-sm outline-none focus:border-violet-400/25" /></div><div className="mt-2 max-h-52 space-y-1 overflow-y-auto">{loading ? <p className="p-3 text-xs text-white/25">Chargement des comptes…</p> : visibleAccounts.length ? visibleAccounts.map((row) => <button key={row.userId} onClick={() => onChange([...draft.collaborators, { userId: row.userId, displayName: row.displayName, avatarUrl: row.discordAvatarUrl || null, permission: "EDIT", color: COLORS[draft.collaborators.length % COLORS.length] }])} className="flex w-full items-center gap-3 rounded-lg p-2 text-left hover:bg-white/[0.05]"><DiscordAvatar name={row.displayName} url={row.discordAvatarUrl} size={34}/><div className="min-w-0 flex-1"><p className="truncate text-sm">{row.displayName}</p><p className="truncate text-[10px] text-white/20">{row.userId}</p></div><Plus className="h-4 w-4 text-violet-300/50"/></button>) : <p className="p-3 text-xs text-white/25">Aucun autre compte disponible.</p>}</div></div> : null}
    <p className="mt-5 flex items-center gap-2 text-xs leading-5 text-emerald-300/45"><span className="h-2 w-2 rounded-full bg-emerald-400"/>Synchronisation automatique activée pour cet atelier.</p>
  </motion.div></motion.div>;
}

function Member({ name, avatar, label }: { name: string; avatar: string | null; label: string }) { return <div className="flex items-center gap-3"><DiscordAvatar name={name} url={avatar} size={38} /><div><p className="text-sm">{name}</p><p className="text-xs text-violet-300/50">{label}</p></div></div>; }

type LivePeer = { userId: string; name: string; avatarUrl: string | null; color: string; x?: number; y?: number };

function useWorkshopPresence(workshopId: string, actor: { id: string; name: string; avatarUrl: string | null }, onRemoteChange: (patch: Partial<SceneWorkshop>) => void) {
  const [peers, setPeers] = useState<LivePeer[]>([]);
  const channelRef = useRef<ReturnType<NonNullable<ReturnType<typeof getSupabaseBrowserClient>>["channel"]> | null>(null);
  useEffect(() => {
    const supabase = getSupabaseBrowserClient();
    if (!supabase) return;
    const color = COLORS[Math.abs(actor.id.split("").reduce((sum, char) => sum + char.charCodeAt(0), 0)) % COLORS.length];
    const channel = supabase.channel(`scene-workshop:${workshopId}`, { config: { presence: { key: actor.id }, broadcast: { self: false } } });
    channelRef.current = channel;
    const syncPresence = () => {
      const state = channel.presenceState<LivePeer>();
      const online = Object.values(state).flat().map((entry) => ({ ...entry }));
      setPeers((current) => online.map((peer) => ({ ...peer, x: current.find((row) => row.userId === peer.userId)?.x, y: current.find((row) => row.userId === peer.userId)?.y })));
    };
    channel.on("presence", { event: "sync" }, syncPresence).on("broadcast", { event: "workshop-change" }, ({ payload }) => {
      const message = payload as { senderId?: string; patch?: Partial<SceneWorkshop> };
      if (message.senderId !== actor.id && message.patch) onRemoteChange(message.patch);
    }).on("broadcast", { event: "cursor" }, ({ payload }) => {
      const cursor = payload as LivePeer;
      setPeers((current) => current.some((peer) => peer.userId === cursor.userId) ? current.map((peer) => peer.userId === cursor.userId ? { ...peer, ...cursor } : peer) : [...current, cursor]);
    }).subscribe(async (status) => {
      if (status === "SUBSCRIBED") await channel.track({ userId: actor.id, name: actor.name, avatarUrl: actor.avatarUrl, color });
    });
    let lastSent = 0;
    const move = (event: PointerEvent) => {
      const now = Date.now(); if (now - lastSent < 45) return; lastSent = now;
      void channel.send({ type: "broadcast", event: "cursor", payload: { userId: actor.id, name: actor.name, avatarUrl: actor.avatarUrl, color, x: event.clientX / window.innerWidth, y: event.clientY / window.innerHeight } });
    };
    window.addEventListener("pointermove", move, { passive: true });
    return () => { window.removeEventListener("pointermove", move); channelRef.current = null; void supabase.removeChannel(channel); };
  }, [actor.avatarUrl, actor.id, actor.name, onRemoteChange, workshopId]);
  const broadcastChange = useCallback((patch: Partial<SceneWorkshop>) => { const channel = channelRef.current; if (channel) void channel.send({ type: "broadcast", event: "workshop-change", payload: { senderId: actor.id, patch } }); }, [actor.id]);
  return { peers, broadcastChange };
}

function LiveCursors({ peers }: { peers: LivePeer[] }) {
  return <>{peers.filter((peer) => typeof peer.x === "number" && typeof peer.y === "number").map((peer) => <motion.div key={peer.userId} className="pointer-events-none fixed left-0 top-0 z-[70] flex items-start gap-1.5" animate={{ x: (peer.x ?? 0) * (typeof window === "undefined" ? 1200 : window.innerWidth), y: (peer.y ?? 0) * (typeof window === "undefined" ? 800 : window.innerHeight) }} transition={{ type: "spring", damping: 30, stiffness: 350, mass: .35 }}><MousePointer2 className="h-5 w-5 -rotate-12 drop-shadow" style={{ color: peer.color }} /><span className="flex items-center gap-1.5 rounded-full px-2 py-1 text-[10px] font-medium text-slate-950 shadow-lg" style={{ backgroundColor: peer.color }}><DiscordAvatar name={peer.name} url={peer.avatarUrl} size={18}/>{peer.name}</span></motion.div>)}</>;
}

function WebMapPanel({ items, disabled, onChange }: { items: WorkshopBoardItem[]; disabled: boolean; onChange: (items: WorkshopBoardItem[]) => void }) {
  const url =
    process.env.NEXT_PUBLIC_WEBMAP_URL?.trim() ||
    "https://webmap.dynasty8.fbfa.fr/map.svg";
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [mode, setMode] = useState<"navigate" | "route" | "arrow">("navigate");
  const [color, setColor] = useState("#fb7185");
  const active = useRef<{ start: { x: number; y: number }; points: { x: number; y: number }[] } | null>(null);
  const render = useCallback(() => { const canvas=canvasRef.current;if(!canvas)return;const rect=canvas.getBoundingClientRect();const ratio=window.devicePixelRatio||1;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);const ctx=canvas.getContext("2d");if(!ctx)return;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,rect.width,rect.height);items.forEach((item)=>drawItem(ctx,item)); }, [items]);
  useEffect(() => { render(); const observer=new ResizeObserver(render);if(canvasRef.current)observer.observe(canvasRef.current);return()=>observer.disconnect(); }, [render]);
  const point=(event:React.PointerEvent<HTMLCanvasElement>)=>{const rect=event.currentTarget.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top};};
  const down=(event:React.PointerEvent<HTMLCanvasElement>)=>{if(disabled||mode==="navigate")return;event.currentTarget.setPointerCapture(event.pointerId);const start=point(event);active.current={start,points:[start]};};
  const move=(event:React.PointerEvent<HTMLCanvasElement>)=>{if(!active.current||mode!=="route")return;const next=point(event);const last=active.current.points.at(-1)!;if(Math.hypot(next.x-last.x,next.y-last.y)>4)active.current.points.push(next);};
  const up=(event:React.PointerEvent<HTMLCanvasElement>)=>{const drawing=active.current;if(!drawing)return;const end=point(event);active.current=null;const item:WorkshopBoardItem=mode==="route"?{id:crypto.randomUUID(),type:"path",color,width:6,points:[...drawing.points,end]}:{id:crypto.randomUUID(),type:"arrow",color,width:6,x:drawing.start.x,y:drawing.start.y,endX:end.x,endY:end.y};onChange([...items,item]);};
  return <div className="mx-auto max-w-[1500px] overflow-hidden rounded-2xl border border-white/[0.08] bg-[#0d1015] shadow-2xl"><div className="flex flex-wrap items-center gap-2 border-b border-white/[0.07] p-3"><div className="mr-auto"><p className="text-sm font-medium">WebMap annotable</p><p className="mt-1 text-xs text-white/30">Navigue sur la carte ou dessine un itinéraire visible en direct par les autres GM.</p></div><button onClick={()=>setMode("navigate")} className={cn("rounded-lg px-3 py-2 text-xs",mode==="navigate"?"bg-violet-400 text-slate-950":"bg-white/[0.05] text-white/55")}><MousePointer2 className="mr-1.5 inline h-4 w-4"/>Naviguer</button><button disabled={disabled} onClick={()=>setMode("route")} className={cn("rounded-lg px-3 py-2 text-xs disabled:opacity-30",mode==="route"?"bg-violet-400 text-slate-950":"bg-white/[0.05] text-white/55")}><Brush className="mr-1.5 inline h-4 w-4"/>Itinéraire</button><button disabled={disabled} onClick={()=>setMode("arrow")} className={cn("rounded-lg px-3 py-2 text-xs disabled:opacity-30",mode==="arrow"?"bg-violet-400 text-slate-950":"bg-white/[0.05] text-white/55")}><ChevronRight className="mr-1.5 inline h-4 w-4"/>Flèche</button>{COLORS.slice(0,5).map((value)=><button key={value} onClick={()=>setColor(value)} className={cn("h-6 w-6 rounded-full border",color===value?"scale-110 border-white":"border-white/15")} style={{backgroundColor:value}}/>)}<button disabled={!items.length||disabled} onClick={()=>onChange(items.slice(0,-1))} className="rounded-lg p-2 text-white/45 hover:bg-white/[0.06] disabled:opacity-20" title="Annuler le dernier tracé"><Undo2 className="h-4 w-4"/></button><button disabled={!items.length||disabled} onClick={()=>{if(confirm("Effacer les annotations de la carte ?"))onChange([]);}} className="rounded-lg p-2 text-white/45 hover:bg-rose-400/10 hover:text-rose-300 disabled:opacity-20" title="Effacer les annotations"><Eraser className="h-4 w-4"/></button><a href={url} target="_blank" rel="noreferrer" className="rounded-lg p-2 text-white/45 hover:bg-white/[0.06]" title="Ouvrir la carte seule"><ExternalLink className="h-4 w-4"/></a></div><div className="relative h-[calc(100dvh-245px)] min-h-[600px] overflow-hidden"><iframe title="WebMap Dynasty 8" src={url} loading="lazy" className={cn("absolute inset-0 h-full w-full border-0 bg-[#111]",mode!=="navigate"&&"pointer-events-none")} /><canvas ref={canvasRef} onPointerDown={down} onPointerMove={move} onPointerUp={up} className={cn("absolute inset-0 h-full w-full touch-none",mode==="navigate"?"pointer-events-none":"cursor-crosshair")} /><div className="pointer-events-none absolute bottom-4 left-4 rounded-lg bg-black/70 px-3 py-2 text-xs text-white/60">{mode==="navigate"?"Mode navigation. Déplace et zoome la carte":"Maintiens et trace directement sur la carte"}</div></div></div>;
}

function InfoNetwork({ blocks, connections, disabled, onBlocks, onConnections }: { blocks: SceneWorkshop["infoBlocks"]; connections: SceneWorkshop["connections"]; disabled: boolean; onBlocks: (blocks: SceneWorkshop["infoBlocks"]) => void; onConnections: (connections: SceneWorkshop["connections"]) => void }) {
  const [source, setSource] = useState<string | null>(null);
  const add = () => { const title=prompt("Titre de l'idée");if(!title?.trim())return;const body=prompt("Informations (optionnel)")||"";onBlocks([...blocks,{id:crypto.randomUUID(),title:title.trim(),body,color:COLORS[blocks.length%COLORS.length],x:0,y:0}]); };
  const edit = (id:string) => { const block=blocks.find((item)=>item.id===id);if(!block)return;const title=prompt("Titre",block.title);if(title===null)return;const body=prompt("Informations",block.body);if(body===null)return;onBlocks(blocks.map((item)=>item.id===id?{...item,title:title.trim()||"Information",body}:item)); };
  const connect = (id:string) => { if(!source){setSource(id);return;}if(source!==id&&!connections.some((line)=>line.fromId===source&&line.toId===id))onConnections([...connections,{id:crypto.randomUUID(),fromId:source,toId:id,color:blocks.find((item)=>item.id===source)?.color||COLORS[0]}]);setSource(null); };
  const remove = (id:string) => { onBlocks(blocks.filter((item)=>item.id!==id));onConnections(connections.filter((line)=>line.fromId!==id&&line.toId!==id)); };
  return <div className="mx-auto max-w-6xl rounded-2xl border border-white/[0.08] bg-[#0e1117] p-4 shadow-2xl sm:p-6"><div className="flex flex-wrap items-center gap-3 border-b border-white/[0.07] pb-4"><div className="mr-auto"><h2 className="text-sm font-medium">Organisation de la scène</h2><p className="mt-1 text-xs text-white/35">Une carte = une idée. Clique sur Relier, puis sur la carte de destination.</p></div><button disabled={disabled} onClick={add} className="flex items-center gap-2 rounded-xl bg-violet-400 px-4 py-2.5 text-xs font-semibold text-slate-950 disabled:opacity-30"><Plus className="h-4 w-4"/>Ajouter une idée</button>{source?<button onClick={()=>setSource(null)} className="rounded-xl border border-violet-400/20 bg-violet-400/10 px-3 py-2.5 text-xs text-violet-200">Choisis une destination · Annuler</button>:null}</div>{blocks.length?<div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{blocks.map((block)=><article key={block.id} className={cn("rounded-xl border bg-white/[0.025] p-4 transition",source===block.id&&"ring-2 ring-violet-400/40")} style={{borderColor:`${block.color}45`}}><div className="flex items-start gap-3"><span className="mt-1 h-3 w-3 shrink-0 rounded-full" style={{backgroundColor:block.color}}/><div className="min-w-0 flex-1"><h3 className="break-words text-sm font-semibold text-white/85">{block.title}</h3><p className="mt-2 whitespace-pre-wrap break-words text-xs leading-5 text-white/40">{block.body||"Aucun détail"}</p></div></div><div className="mt-4 flex gap-2 border-t border-white/[0.06] pt-3"><button disabled={disabled} onClick={()=>edit(block.id)} className="rounded-lg bg-white/[0.04] px-2.5 py-1.5 text-[11px] text-white/55 hover:bg-white/[0.08]">Modifier</button><button disabled={disabled} onClick={()=>connect(block.id)} className="rounded-lg bg-violet-400/[0.08] px-2.5 py-1.5 text-[11px] text-violet-200/70 hover:bg-violet-400/15">{source&&source!==block.id?"Relier ici":"Relier"}</button><button disabled={disabled} onClick={()=>remove(block.id)} className="ml-auto rounded-lg px-2.5 py-1.5 text-[11px] text-white/30 hover:bg-rose-400/10 hover:text-rose-300">Supprimer</button></div></article>)}</div>:<button disabled={disabled} onClick={add} className="mt-8 flex w-full flex-col items-center rounded-2xl border border-dashed border-white/10 py-14 text-white/30 hover:border-violet-400/20 hover:text-violet-200/60"><Plus className="mb-3 h-7 w-7"/><span className="text-sm">Ajoute la première idée de ta scène</span></button>}{connections.length?<div className="mt-6 border-t border-white/[0.07] pt-4"><p className="mb-3 text-xs uppercase tracking-wider text-white/30">Liens entre les idées</p><div className="flex flex-wrap gap-2">{connections.map((line)=>{const from=blocks.find((item)=>item.id===line.fromId);const to=blocks.find((item)=>item.id===line.toId);if(!from||!to)return null;return <button key={line.id} disabled={disabled} onClick={()=>onConnections(connections.filter((item)=>item.id!==line.id))} title="Cliquer pour supprimer ce lien" className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1.5 text-xs text-white/50 hover:border-rose-400/20 hover:text-rose-200">{from.title} <span className="px-1 text-violet-300">→</span> {to.title}</button>;})}</div></div>:null}</div>;
}

function LegacyInfoNetwork({ blocks, connections, disabled, onBlocks, onConnections }: { blocks: SceneWorkshop["infoBlocks"]; connections: SceneWorkshop["connections"]; disabled: boolean; onBlocks: (blocks: SceneWorkshop["infoBlocks"]) => void; onConnections: (connections: SceneWorkshop["connections"]) => void }) {
  const [localBlocks, setLocalBlocks] = useState(blocks);
  const [linkFrom, setLinkFrom] = useState<string | null>(null);
  const drag = useRef<{ id: string; dx: number; dy: number } | null>(null);
  useEffect(() => { if (!drag.current) setLocalBlocks(blocks); }, [blocks]);
  function addBlock() { const title=prompt("Nom de l'idée ou de l'information");if(!title?.trim())return;const body=prompt("Détails (optionnel)")||"";const index = localBlocks.length; onBlocks([...localBlocks, { id: crypto.randomUUID(), title: title.trim(), body, color: COLORS[index % COLORS.length], x: 60 + (index % 4) * 270, y: 70 + Math.floor(index / 4) * 180 }]); }
  function editBlock(id: string) { if (disabled) return; const block = localBlocks.find((row) => row.id === id); if (!block) return; const title = prompt("Titre du bloc", block.title); if (title === null) return; const body = prompt("Informations", block.body); if (body === null) return; onBlocks(localBlocks.map((row) => row.id === id ? { ...row, title: title.trim() || "Information", body } : row)); }
  function clickConnector(id: string) { if (disabled) return; if (!linkFrom) { setLinkFrom(id); return; } if (linkFrom !== id && !connections.some((line) => line.fromId === linkFrom && line.toId === id)) onConnections([...connections, { id: crypto.randomUUID(), fromId: linkFrom, toId: id, color: localBlocks.find((row) => row.id === linkFrom)?.color || COLORS[0] }]); setLinkFrom(null); }
  return <div className="mx-auto max-w-[1500px] overflow-hidden rounded-2xl border border-white/[0.08] bg-[#0e1117] shadow-2xl"><div className="flex flex-wrap items-center gap-3 border-b border-white/[0.07] bg-[#11141a] p-3"><button disabled={disabled} onClick={addBlock} className="flex items-center gap-2 rounded-xl bg-violet-400 px-3.5 py-2.5 text-xs font-semibold text-slate-950 disabled:opacity-30"><Plus className="h-4 w-4"/>Ajouter un bloc</button><p className="text-xs text-white/30">Utilise les points lumineux pour relier les informations. Double-clique sur un bloc pour l’éditer.</p>{linkFrom ? <button onClick={() => setLinkFrom(null)} className="ml-auto rounded-lg border border-violet-400/20 bg-violet-400/10 px-3 py-2 text-xs text-violet-200">Connexion en cours · Annuler</button> : null}</div><div className="relative h-[calc(100dvh-245px)] min-h-[620px] overflow-auto bg-[radial-gradient(circle_at_center,rgba(56,189,248,.045),transparent_55%)]"><div className="relative h-[1100px] w-[1600px] bg-[radial-gradient(rgba(255,255,255,.07)_1px,transparent_1px)] [background-size:24px_24px]"><svg className="pointer-events-none absolute inset-0 h-full w-full">{connections.map((line) => { const from=localBlocks.find((b)=>b.id===line.fromId);const to=localBlocks.find((b)=>b.id===line.toId);if(!from||!to)return null;const x1=from.x+230,y1=from.y+65,x2=to.x,y2=to.y+65,curve=Math.max(70,Math.abs(x2-x1)*.45);return <g key={line.id}><path d={`M ${x1} ${y1} C ${x1+curve} ${y1}, ${x2-curve} ${y2}, ${x2} ${y2}`} fill="none" stroke={line.color} strokeOpacity=".5" strokeWidth="3"/><circle cx={x2} cy={y2} r="5" fill={line.color}/></g>;})}</svg>{localBlocks.map((block) => <div key={block.id} onDoubleClick={() => editBlock(block.id)} onPointerDown={(event) => { if(disabled || (event.target as HTMLElement).dataset.connector)return; const rect=event.currentTarget.getBoundingClientRect();drag.current={id:block.id,dx:event.clientX-rect.left,dy:event.clientY-rect.top};event.currentTarget.setPointerCapture(event.pointerId); }} onPointerMove={(event) => { if(drag.current?.id!==block.id)return;const parent=event.currentTarget.parentElement?.getBoundingClientRect();if(!parent)return;setLocalBlocks((rows)=>rows.map((row)=>row.id===block.id?{...row,x:Math.max(0,event.clientX-parent.left-drag.current!.dx),y:Math.max(0,event.clientY-parent.top-drag.current!.dy)}:row)); }} onPointerUp={() => { if(drag.current?.id===block.id){drag.current=null;onBlocks(localBlocks);} }} className="group absolute w-[230px] cursor-grab select-none rounded-2xl border bg-[#141820]/95 p-4 shadow-2xl backdrop-blur active:cursor-grabbing" style={{left:block.x,top:block.y,borderColor:`${block.color}55`,boxShadow:`0 18px 50px #0008,0 0 30px ${block.color}10`}}><div className="flex items-start gap-3"><span className="mt-1 h-3 w-3 shrink-0 rounded-full" style={{backgroundColor:block.color,boxShadow:`0 0 14px ${block.color}`}}/><div className="min-w-0 flex-1"><p className="break-words text-sm font-semibold text-white/85">{block.title}</p><p className="mt-2 whitespace-pre-wrap break-words text-xs leading-5 text-white/40">{block.body}</p></div></div><button data-connector="true" title={linkFrom ? "Relier à ce bloc" : "Commencer une liaison"} onClick={() => clickConnector(block.id)} className={cn("absolute -right-2.5 top-1/2 h-5 w-5 -translate-y-1/2 rounded-full border-2 border-[#0e1117] transition hover:scale-125",linkFrom===block.id&&"animate-pulse scale-125")} style={{backgroundColor:block.color,boxShadow:`0 0 15px ${block.color}`}}/><button onClick={() => {onBlocks(localBlocks.filter((row)=>row.id!==block.id));onConnections(connections.filter((line)=>line.fromId!==block.id&&line.toId!==block.id));}} className="absolute -right-2 -top-2 hidden rounded-full bg-rose-500 p-1 text-white group-hover:block"><X className="h-3 w-3"/></button></div>)}</div></div></div>;
}

function WorkshopBoard({ items, onChange, disabled }: { items: WorkshopBoardItem[]; onChange: (items: WorkshopBoardItem[]) => void; disabled: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null); const imageInput = useRef<HTMLInputElement>(null);
  const [tool, setTool] = useState<Tool>("pen"); const [color, setColor] = useState(COLORS[0]); const [width, setWidth] = useState(4);
  const drawing = useRef<{ start: { x: number; y: number }; points: { x: number; y: number }[] } | null>(null);
  const [history, setHistory] = useState<WorkshopBoardItem[][]>([]); const [future, setFuture] = useState<WorkshopBoardItem[][]>([]);
  const render = useCallback(() => { const canvas = canvasRef.current; if (!canvas) return; const rect = canvas.getBoundingClientRect(); const ratio = window.devicePixelRatio || 1; if (canvas.width !== rect.width * ratio || canvas.height !== rect.height * ratio) { canvas.width = rect.width * ratio; canvas.height = rect.height * ratio; } const ctx = canvas.getContext("2d"); if (!ctx) return; ctx.setTransform(ratio,0,0,ratio,0,0); ctx.clearRect(0,0,rect.width,rect.height); ctx.fillStyle="#0e1117"; ctx.fillRect(0,0,rect.width,rect.height); ctx.strokeStyle="rgba(255,255,255,.035)"; ctx.lineWidth=1; for(let x=0;x<rect.width;x+=32){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,rect.height);ctx.stroke();} for(let y=0;y<rect.height;y+=32){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(rect.width,y);ctx.stroke();} items.forEach((item) => drawItem(ctx,item)); }, [items]);
  useEffect(() => { render(); const obs = new ResizeObserver(render); if (canvasRef.current) obs.observe(canvasRef.current); return () => obs.disconnect(); }, [render]);
  function point(e: React.PointerEvent<HTMLCanvasElement>) { const rect=e.currentTarget.getBoundingClientRect(); return {x:e.clientX-rect.left,y:e.clientY-rect.top}; }
  function commit(next: WorkshopBoardItem[]) { setHistory((h)=>[...h.slice(-30),items]); setFuture([]); onChange(next); }
  function down(e: React.PointerEvent<HTMLCanvasElement>) { if(disabled||tool==="select")return; e.currentTarget.setPointerCapture(e.pointerId); const p=point(e); drawing.current={start:p,points:[p]}; }
  function move(e: React.PointerEvent<HTMLCanvasElement>) { if(!drawing.current)return; const p=point(e); drawing.current.points.push(p); const ctx=e.currentTarget.getContext("2d"); if(tool==="pen"&&ctx){const prev=drawing.current.points.at(-2)!;ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap="round";ctx.beginPath();ctx.moveTo(prev.x,prev.y);ctx.lineTo(p.x,p.y);ctx.stroke();} }
  function up(e: React.PointerEvent<HTMLCanvasElement>) { const active=drawing.current;if(!active)return; const p=point(e); let item:WorkshopBoardItem;if(tool==="pen")item={id:crypto.randomUUID(),type:"path",color,width,points:active.points};else if(tool==="rect")item={id:crypto.randomUUID(),type:"rect",color,width,x:active.start.x,y:active.start.y,w:p.x-active.start.x,h:p.y-active.start.y};else item={id:crypto.randomUUID(),type:"arrow",color,width,x:active.start.x,y:active.start.y,endX:p.x,endY:p.y};drawing.current=null;commit([...items,item]); }
  function addNote(){const text=prompt("Texte de la note");if(text)commit([...items,{id:crypto.randomUUID(),type:"note",color,x:80+items.length*8,y:70+items.length*8,w:220,h:130,text}]);}
  function addImage(file?:File){if(!file)return;if(file.size>350_000){alert("Image trop lourde (350 Ko maximum). Compresse-la avant de l’ajouter.");return;}const reader=new FileReader();reader.onload=()=>commit([...items,{id:crypto.randomUUID(),type:"image",src:String(reader.result),x:70,y:70,w:420,h:260}]);reader.readAsDataURL(file);}
  return <div className="mx-auto flex max-w-[1500px] flex-col overflow-hidden rounded-2xl border border-white/[0.08] bg-[#0e1117] shadow-2xl"><div className="flex flex-wrap items-center gap-1.5 border-b border-white/[0.07] bg-[#11141a] p-2.5"><BoardButton active={tool==="select"} title="Sélection" onClick={()=>setTool("select")}><MousePointer2 /></BoardButton><BoardButton active={tool==="pen"} title="Dessiner" onClick={()=>setTool("pen")}><Brush /></BoardButton><BoardButton active={tool==="rect"} title="Rectangle" onClick={()=>setTool("rect")}><RectangleHorizontal /></BoardButton><BoardButton active={tool==="arrow"} title="Flèche" onClick={()=>setTool("arrow")}><ChevronRight /></BoardButton><span className="mx-1 h-6 w-px bg-white/10" />{COLORS.map(c=><button key={c} title={c} onClick={()=>setColor(c)} className={cn("h-6 w-6 rounded-full border transition",color===c?"scale-110 border-white":"border-white/15")} style={{backgroundColor:c}} />)}<input type="range" min="2" max="14" value={width} onChange={(e)=>setWidth(Number(e.target.value))} className="ml-2 w-20 accent-violet-400" /><span className="mx-1 h-6 w-px bg-white/10" /><BoardButton title="Note" onClick={addNote}><StickyNote /></BoardButton><BoardButton title="Ajouter une photo" onClick={()=>imageInput.current?.click()}><ImagePlus /></BoardButton><input ref={imageInput} type="file" accept="image/*" hidden onChange={(e)=>{addImage(e.target.files?.[0]);e.currentTarget.value="";}}/><div className="ml-auto flex gap-1"><BoardButton disabled={!history.length} title="Annuler" onClick={()=>{const previous=history.at(-1);if(!previous)return;setFuture(f=>[items,...f]);setHistory(h=>h.slice(0,-1));onChange(previous);}}><Undo2 /></BoardButton><BoardButton disabled={!future.length} title="Rétablir" onClick={()=>{const next=future[0];setHistory(h=>[...h,items]);setFuture(f=>f.slice(1));onChange(next);}}><Redo2 /></BoardButton><BoardButton disabled={!items.length} title="Tout effacer" onClick={()=>{if(confirm("Effacer tout le plan ?"))commit([]);}}><Eraser /></BoardButton></div></div><div className="relative h-[calc(100dvh-235px)] min-h-[560px] overflow-hidden"><canvas ref={canvasRef} onPointerDown={down} onPointerMove={move} onPointerUp={up} className={cn("h-full w-full touch-none",tool==="pen"?"cursor-crosshair":"cursor-default")} /><div className="pointer-events-none absolute bottom-4 left-4 rounded-lg border border-white/[0.06] bg-black/50 px-3 py-2 text-[10px] uppercase tracking-wider text-white/25">Plan sauvegardé automatiquement</div></div></div>;
}

function BoardButton({ children, onClick, title, active, disabled }: { children: React.ReactNode; onClick:()=>void; title:string; active?:boolean; disabled?:boolean }) { return <button disabled={disabled} title={title} onClick={onClick} className={cn("flex h-9 w-9 items-center justify-center rounded-lg text-white/40 transition [&>svg]:h-4 [&>svg]:w-4",active?"bg-violet-400/15 text-violet-300":"hover:bg-white/[0.06] hover:text-white",disabled&&"opacity-20")} >{children}</button>; }

function drawItem(ctx:CanvasRenderingContext2D,item:WorkshopBoardItem){ctx.save();if(item.type==="path"){ctx.strokeStyle=item.color;ctx.lineWidth=item.width;ctx.lineCap="round";ctx.lineJoin="round";ctx.beginPath();item.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();}else if(item.type==="rect"){ctx.strokeStyle=item.color;ctx.lineWidth=item.width;ctx.strokeRect(item.x,item.y,item.w,item.h);}else if(item.type==="arrow"){ctx.strokeStyle=item.color;ctx.fillStyle=item.color;ctx.lineWidth=item.width;ctx.beginPath();ctx.moveTo(item.x,item.y);ctx.lineTo(item.endX,item.endY);ctx.stroke();const angle=Math.atan2(item.endY-item.y,item.endX-item.x);ctx.beginPath();ctx.moveTo(item.endX,item.endY);ctx.lineTo(item.endX-14*Math.cos(angle-.5),item.endY-14*Math.sin(angle-.5));ctx.lineTo(item.endX-14*Math.cos(angle+.5),item.endY-14*Math.sin(angle+.5));ctx.closePath();ctx.fill();}else if(item.type==="note"){ctx.fillStyle=item.color+"dd";ctx.shadowColor="#0008";ctx.shadowBlur=15;ctx.fillRect(item.x,item.y,item.w,item.h);ctx.shadowBlur=0;ctx.fillStyle="#071019";ctx.font="600 15px system-ui";wrapText(ctx,item.text,item.x+15,item.y+28,item.w-30,22);}else{const img=new Image();img.onload=()=>ctx.drawImage(img,item.x,item.y,item.w,item.h);img.src=item.src;}ctx.restore();}
function wrapText(ctx:CanvasRenderingContext2D,text:string,x:number,y:number,max:number,line:number){const words=text.split(" ");let row="";for(const word of words){const test=row+word+" ";if(ctx.measureText(test).width>max&&row){ctx.fillText(row,x,y);row=word+" ";y+=line;}else row=test;}ctx.fillText(row,x,y);}
